    .keys(electionPrefixes[activeElectionLevel] || {})
    .map(Number)
    .sort((a, b) => a - b);

  // ——— 3. Хук загрузки данных ———
  useEffect(() => {
    // Если год выпал из доступных — сбросить и выйти только из эффекта
    if (availableYears.length && !availableYears.includes(year)) {
      setYear(availableYears[0]);
      return;        // <— это return **изнутри** useEffect, а не из App!
    }

    const base = process.env.PUBLIC_URL + "/data";
    let districtUrl = "", uikUrl = null;

    switch (activeElectionLevel) {
      case "Мэр":
        districtUrl = `${base}/districts_with_${year}_mer.geojson`;
        uikUrl      = `${base}/united_uiks_with_final_${year}_mer.geojson`;
        break;
      case "Президент":
        districtUrl = `${base}/moscow_${year}_president_results.geojson`;
        uikUrl      = `${base}/uik_results_${year}_president.geojson`;
        break;
      case "Госдума":
        districtUrl = `${base}/moscow_${year}_duma_results.geojson`;
        if (activeListType === "Список") {
          uikUrl = null;
        } else {
          uikUrl = `${base}/uik_results_${year}_duma_${activeListType.toLowerCase()}.geojson`;
        }
        break;
      default:
        return; // если уровень не узнаем — просто выйдем из эффекта
    }

    // 3.1 фетчим районы
    fetch(districtUrl)
      .then(r => r.json())
      .then(data => {
        setDistrictData(data);
        const prefix = electionPrefixes[activeElectionLevel][year];
        setDistrictLegendLevels(getAdvantageLevels(data.features, `${year}_${prefix}_`));
      });

    // 3.2 фетчим УИК или сбрасываем
    if (uikUrl) {
      fetch(uikUrl)
        .then(r => r.json())
        .then(data => {
          setUikData(data);
          const prefix = electionPrefixes[activeElectionLevel][year];
          setLegendLevels(getAdvantageLevels(data.features, `${year}_${prefix}_`));
        });
    } else {
      setLegendLevels({});
    }
  }, [year, activeElectionLevel, activeListType, availableYears]);

